welcome.styles:
:root{--ink:#254c50;--muted:#627777;--paper:#faf9f5;--mint:#e1efea;--sky:#e7eff7;--peach:#f7dfcf;--line:#dce5df;--teal:#397b78}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,-apple-system,sans-serif}a{color:inherit}button{font:inherit;cursor:pointer}header{background:#fff;border-bottom:1px solid var(--line)}.top{max-width:1200px;margin:auto;padding:14px 28px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{max-width:360px}.brand img{width:100%;height:auto;display:block}.brand small{display:block;padding-left:23%;font-size:10px;color:var(--muted);margin-top:-8px}.login{background:transparent;border:1px solid #b3c9c3;border-radius:30px;padding:10px 22px;font-weight:600}.login:hover{background:var(--mint)}main{max-width:1200px;margin:auto;padding:0 28px}.hero{text-align:center;padding:55px 0 36px;position:relative}.eyebrow{font-size:11px;letter-spacing:2px;font-weight:700;color:var(--teal)}h1{font-size:clamp(34px,4.5vw,56px);line-height:1.2;letter-spacing:-1.8px;margin:17px 0 20px;font-weight:700}h1 span{color:var(--teal)}.hero p{max-width:850px;margin:auto;color:var(--muted);font-size:18px}.choose{text-align:center;font-size:14px;color:var(--muted);margin:0 0 20px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.card{padding:28px;border:1px solid var(--line);border-radius:23px;background:#fff;display:flex;flex-direction:column;align-items:flex-start;position:relative}.card.one{background:linear-gradient(150deg,#e1efea 0%,#f5faf6 100%)}.card.two{background:linear-gradient(150deg,#e7eff7 0%,#f5f8fc 100%)}.card.three{background:linear-gradient(150deg,#f7dfcf 0%,#fcf6f0 100%)}.icon{width:55px;height:55px;display:grid;place-items:center;border-radius:17px;background:#ffffffb0;margin-bottom:22px}.icon svg{width:30px;height:30px;stroke:var(--ink);stroke-width:1.7;fill:none;stroke-linecap:round;stroke-linejoin:round}.label{font-size:10px;letter-spacing:1.3px;font-weight:700;color:var(--muted);margin-bottom:9px}.card h2{font-size:24px;letter-spacing:-.6px;line-height:1.25;margin:0 0 14px}.card p{font-size:15px;color:#516c6d;margin:0 0 20px;flex:1}.card ul{list-style:none;padding:0;margin:0 0 26px;font-size:13px;color:#516c6d}.card li{margin:6px 0}.card li::before{content:'✓';margin-right:9px;color:var(--teal)}.action{width:100%;padding:12px 16px;background:var(--ink);border:0;border-radius:12px;color:white;font-size:14px;font-weight:600;display:flex;align-items:center;justify-content:space-between}.action:hover{background:var(--teal)}.card small{margin-top:12px;color:var(--muted);font-size:11px}.representations{margin:44px 0 36px;display:grid;grid-template-columns:1fr 1.15fr;gap:35px;align-items:center;border-top:1px solid var(--line);padding-top:36px}.representations h2{font-size:27px;letter-spacing:-.7px;line-height:1.3;margin:10px 0 15px}.representations p{color:var(--muted);font-size:15px}.rep-art{display:flex;align-items:center;justify-content:space-around;gap:12px;background:white;border:1px solid var(--line);border-radius:20px;padding:23px 16px}.rep{display:flex;flex-direction:column;align-items:center;gap:8px;min-width:0}.rep svg{height:75px;width:110px}.rep small{font-size:11px;color:var(--muted)}.formula{height:75px;display:flex;align-items:center;font-size:21px;white-space:nowrap}.formula b{color:#a54e40;font-weight:500}.equal{color:#9aada7}.molecule-name{font-size:14px;color:var(--teal);font-weight:650;text-align:center;margin-top:12px}.footer{border-top:1px solid var(--line);padding:20px 0;display:flex;justify-content:space-between;gap:20px;color:var(--muted);font-size:11px}.footer a{text-decoration:none}.preview-note{max-width:1200px;margin:0 auto;padding:12px 28px;color:var(--muted);font-size:11px;text-align:center;background:#edf3ef}dialog{border:1px solid var(--line);border-radius:22px;max-width:480px;width:calc(100% - 32px);padding:28px;color:var(--ink);background:var(--paper)}dialog::backdrop{background:#254c5066}dialog h2{margin:0 0 12px;font-size:23px}dialog p{color:var(--muted);font-size:15px}dialog a{display:inline-block;margin:8px 0 18px}dialog button{border:0;border-radius:10px;padding:10px 18px;background:var(--ink);color:white}button:focus-visible,a:focus-visible{outline:3px solid var(--teal);outline-offset:4px}@media(max-width:900px){.cards{grid-template-columns:1fr}.card{padding:24px}.card p{max-width:650px}.card ul{margin-bottom:18px}.icon{margin-bottom:14px}.representations{grid-template-columns:1fr}.action{max-width:350px}.hero{padding:35px 0 28px}.brand{max-width:300px}}@media(max-width:550px){.top{padding:12px 16px;gap:12px}.brand{max-width:245px}.brand small{font-size:8px;margin-top:0}.login{padding:8px 12px;font-size:12px}main{padding:0 18px}h1{letter-spacing:-1px}.hero p{font-size:16px}.rep-art{gap:4px;padding:16px 8px}.rep svg{width:80px}.formula{font-size:16px}.footer{flex-direction:column;gap:8px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}

.rep-art{flex-wrap:wrap;row-gap:20px}.rep .expanded-ethanol{width:155px;height:120px}.ethanol-model{width:190px;height:150px;border:0;background:#fff;border-radius:12px}.formula{height:120px}.rep{flex:0 0 auto}@media(max-width:550px){.rep-art{gap:14px}.rep .expanded-ethanol{width:140px}.ethanol-model{width:210px;height:165px}}

.representations{grid-template-columns:1fr;gap:24px}
.rep-art{justify-content:space-evenly;flex-wrap:nowrap;padding:24px;gap:16px}
.rep{flex:1 1 0;min-width:0}
.rep small{text-align:center}
.rep .formula,.rep .expanded-ethanol,.rep .ethanol-model{height:165px}
.rep .ethanol-model{max-width:100%}
@media(max-width:550px){.rep-art{padding:14px 8px;gap:4px}.rep .formula{font-size:14px}.rep .expanded-ethanol{width:100%;max-width:140px}.rep small{font-size:10px;line-height:1.4}.rep .formula,.rep .expanded-ethanol,.rep .ethanol-model{height:125px}.rep .ethanol-model{width:100%}.equal{font-size:12px}}

.explore-entry{text-align:center;margin-top:24px}.explore-entry a{display:inline-block;padding:12px 22px;border:1px solid #b3c9c3;border-radius:12px;text-decoration:none;font-size:15px;font-weight:600;background:var(--mint)}.explore-entry a:hover{background:#d2e6dd}
.rep img.ethanol-model{display:block;object-fit:contain;background:transparent}
.ethanol-static{position:relative;overflow:hidden;flex-shrink:0}.ethanol-static img{position:absolute;width:170%;max-width:none;height:auto;left:-35%;top:-50%;display:block}

